package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaimReassign {
    public void validate(@RequestBody ClaimReassignRequest request, Out<ClaimReassignment> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        if (request == null || request.toPersonId() == null) {
            throw new InvalidSheetRequestException("A reassignment needs the person to move the claim to");
        }
        actor.set(new Actor(request.user()));
        body.set(new ClaimReassignment(request.toPersonId(), request.user()));
    }
}
-- How many proofs a claim has, raised by one at a time (not on a SETTLED or VOID claim, nor one
-- dated in a closed period). A claim whose due is above the sheet's proof threshold in force on its
-- date cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- A correction is a claim with a negative amount: it names, by number, the SETTLED claim of the
-- same person it corrects. `corrects` is that number; null for any other claim.
ALTER TABLE claim ADD COLUMN corrects BIGINT;
-- `amount` may now be negative (a correction): the column is replaced to drop its `>= 0` check.
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(14,2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;

